toolScript:
let names = ["Ahmed", "Sarah", "Mike", "John", "Fatima", "Ali"];
        let isSpinning = false;
        let gameMode = 'chest';
        let gameType = 'wheel';
        let spinPower = 0;
        let powerInterval = null;
        let isCharging = false;
        let chargeStartTime = 0;
        let lastWinner = null;
        let recentWinners = [];
        let angle = 0;
        let angularVel = 0;

        const canvas = document.getElementById('wheelCanvas');
        const ctx = canvas ? canvas.getContext('2d') : null;
        const spinBtn = document.getElementById('spin-btn');
        const spinBtnText = document.getElementById('spin-btn-text');
        const powerBar = document.getElementById('power-bar');
        const nameInput = document.getElementById('name-input');
        const nameList = document.getElementById('name-list');
        const tipSection = document.getElementById('tip-calculator');
        const countVal = document.getElementById('count-val');
        const statusVal = document.getElementById('status-val');

        const colorsChest = ['#d97706', '#b45309', '#f59e0b', '#ea580c', '#c2410c'];
        const colorsBill = ['#dc2626', '#b91c1c', '#ef4444', '#991b1b', '#ea580c'];

        // Cached Audio instance
        let faaaAudio = null;
        try {
            faaaAudio = new Audio('/assets/audio/mandi_game_faaa_effect.mp3');
            faaaAudio.preload = 'auto';
        } catch (e) {
            console.warn("Audio initialization notice:", e);
        }

        document.addEventListener('DOMContentLoaded', () => {
            loadHistory();
            renderList();
            drawWheel();
            updateUI();
            setupSpinControls();
            setupModalListeners();
        });

        function setupSpinControls() {
            if (!spinBtn) return;

            spinBtn.addEventListener('mousedown', startCharging);
            spinBtn.addEventListener('touchstart', startCharging, { passive: true });

            window.addEventListener('mouseup', handleGlobalRelease);
            window.addEventListener('touchend', handleGlobalRelease);

            spinBtn.addEventListener('click', (e) => {
                // If it was a quick click without significant hold charging
                if (Date.now() - chargeStartTime < 220 && !isSpinning) {
                    handleQuickSpin();
                }
            });

            spinBtn.addEventListener('keydown', (e) => {
                if ((e.key === ' ' || e.key === 'Enter') && !isSpinning) {
                    e.preventDefault();
                    handleQuickSpin();
                }
            });
        }

        function setupModalListeners() {
            const modal = document.getElementById('winner-modal');
            if (modal) {
                modal.addEventListener('click', (e) => {
                    if (e.target.id === 'winner-modal') closeModal();
                });
            }
            window.addEventListener('keydown', (e) => {
                if (e.key === 'Escape') closeModal();
            });
        }

        function handleEnter(e) {
            if (e.key === 'Enter') addName();
        }

        function addName() {
            if (!nameInput) return;
            const val = nameInput.value.trim();
            if (!val) return;
            if (names.includes(val)) {
                shakeInput();
                return;
            }
            names.push(val);
            nameInput.value = '';
            renderList();
            if (gameType === 'wheel') drawWheel();
            else setupPlatter();
            updateUI();
        }

        function togglePasteMode() {
            const pasteArea = document.getElementById('paste-area');
            if (pasteArea) pasteArea.classList.toggle('hidden');
        }

        function processPaste() {
            const pasteInput = document.getElementById('paste-input');
            if (!pasteInput) return;
            const raw = pasteInput.value;
            const split = raw.split(/[\n,]+/).map(n => n.trim()).filter(n => n.length > 0);
            split.forEach(name => {
                if (!names.includes(name)) names.push(name);
            });
            pasteInput.value = '';
            document.getElementById('paste-area').classList.add('hidden');
            renderList();
            if (gameType === 'wheel') drawWheel();
            else setupPlatter();
            updateUI();
        }

        function removeName(name) {
            names = names.filter(n => n !== name);
            renderList();
            if (gameType === 'wheel') drawWheel();
            else setupPlatter();
            updateUI();
        }

        function clearList() {
            names = [];
            renderList();
            drawWheel();
            if (gameType === 'platter') setupPlatter();
            updateUI();
        }

        function quickFill() {
            names = ["Ahmed", "Sarah", "Mike", "John", "Fatima", "Ali"];
            renderList();
            drawWheel();
            if (gameType === 'platter') setupPlatter();
            updateUI();
        }

        function fastAdd() {
            const input = document.getElementById('fast-count');
            const count = parseInt(input.value) || 0;
            if (count < 1) return;
            const existingFriends = names.filter(n => n.startsWith('Player ')).length;
            let startNum = existingFriends + 1;
            for (let i = 0; i < count; i++) {
                names.push(`Player ${startNum + i}`);
            }
            renderList();
            if (gameType === 'wheel') drawWheel();
            else setupPlatter();
            updateUI();

            const btn = document.querySelector('button[onclick="fastAdd()"]');
            if (btn) {
                const oldHTML = btn.innerHTML;
                btn.innerHTML = 'Added!';
                btn.classList.add('text-emerald-600', 'border-emerald-300', 'bg-emerald-50');
                setTimeout(() => {
                    btn.innerHTML = oldHTML;
                    btn.classList.remove('text-emerald-600', 'border-emerald-300', 'bg-emerald-50');
                }, 1000);
            }
        }

        function renderList() {
            if (!nameList) return;
            nameList.innerHTML = '';
            if (names.length === 0) {
                nameList.innerHTML = '<div class="text-center text-slate-400 text-sm py-16 flex flex-col items-center justify-center h-full break-words px-4">List is empty. Add players above to begin.</div>';
                return;
            }
            names.forEach(name => {
                const item = document.createElement('div');
                item.className = 'flex justify-between items-center bg-white border border-slate-200 px-4 py-3 rounded-xl shadow-sm gap-3';
                const safeName = name.replace(/'/g, "\\'");
                item.innerHTML = `
                    <span class="text-sm font-bold text-slate-700 break-words min-w-0 flex-1">${escapeHtml(name)}</span>
                    <button type="button" aria-label="Remove ${escapeHtml(name)}" onclick="removeName('${safeName}')" class="text-slate-400 hover:text-red-500 hover:bg-red-50 p-1.5 rounded-lg transition shrink-0">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                `;
                nameList.appendChild(item);
            });
        }

        function escapeHtml(text) {
            const map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' };
            return text.replace(/[&<>"']/g, m => map[m]);
        }

        function updateUI() {
            if (tipSection) {
                if (gameMode === 'bill' && names.length > 0) {
                    tipSection.classList.remove('hidden');
                } else {
                    tipSection.classList.add('hidden');
                }
            }
            if (countVal) countVal.innerText = names.length;
            if (statusVal) {
                statusVal.innerText = isSpinning ? "SPINNING" : (names.length > 1 ? "READY" : "WAITING");
                statusVal.className = isSpinning ? "text-amber-500 font-bold uppercase text-xs animate-pulse" : "text-slate-400 font-bold uppercase text-xs";
            }
        }

        function setMode(mode) {
            gameMode = mode;
            const btnChest = document.getElementById('btn-mode-chest');
            const btnBill = document.getElementById('btn-mode-bill');
            if (btnChest) {
                btnChest.className = `flex-1 sm:flex-none flex items-center justify-center gap-2 px-5 py-2.5 rounded-lg text-sm font-bold uppercase tracking-wide transition-all select-none active:scale-95 ${mode === 'chest' ? 'bg-amber-500 text-white shadow-lg shadow-amber-500/30' : 'text-slate-300 hover:text-white hover:bg-slate-700/50'}`;
            }
            if (btnBill) {
                btnBill.className = `flex-1 sm:flex-none flex items-center justify-center gap-2 px-5 py-2.5 rounded-lg text-sm font-bold uppercase tracking-wide transition-all select-none active:scale-95 ${mode === 'bill' ? 'bg-red-500 text-white shadow-lg shadow-red-500/30' : 'text-slate-300 hover:text-white hover:bg-slate-700/50'}`;
            }
            drawWheel();
            updateUI();
            if (gameType === 'platter') setupPlatter();
        }

        function switchGameType(type) {
            gameType = type;
            const tabWheel = document.getElementById('tab-wheel');
            const tabPlatter = document.getElementById('tab-platter');
            const wheelContainer = document.getElementById('wheel-container');
            const mysteryGrid = document.getElementById('mystery-grid');
            const spinControls = document.getElementById('spin-controls');

            if (tabWheel) tabWheel.className = `chip text-xs sm:text-sm ${type === 'wheel' ? 'chip-active' : 'chip-inactive'}`;
            if (tabPlatter) tabPlatter.className = `chip text-xs sm:text-sm ${type === 'platter' ? 'chip-active' : 'chip-inactive'}`;

            if (type === 'wheel') {
                if (wheelContainer) wheelContainer.style.display = 'flex';
                if (mysteryGrid) mysteryGrid.style.display = 'none';
                if (spinControls) spinControls.classList.remove('hidden');
                drawWheel();
            } else {
                if (wheelContainer) wheelContainer.style.display = 'none';
                if (mysteryGrid) mysteryGrid.style.display = 'grid';
                if (spinControls) spinControls.classList.add('hidden');
                setupPlatter();
            }
        }

        function drawWheel() {
            if (!ctx) return;
            const center = 400;
            const radius = 380;
            ctx.clearRect(0, 0, 800, 800);

            if (names.length === 0) {
                // Empty state
                ctx.beginPath();
                ctx.arc(center, center, radius, 0, 2 * Math.PI);
                ctx.fillStyle = '#f8fafc';
                ctx.fill();
                ctx.lineWidth = 4;
                ctx.strokeStyle = '#e2e8f0';
                ctx.stroke();

                ctx.textAlign = 'center';
                ctx.fillStyle = '#94a3b8';
                ctx.font = 'bold 28px Inter, sans-serif';
                ctx.fillText('Add at least 2 players to begin', center, center - 10);
                ctx.font = '500 20px Inter, sans-serif';
                ctx.fillText('Use the player list below', center, center + 30);
                return;
            }

            const colors = gameMode === 'chest' ? colorsChest : colorsBill;
            const slice = (2 * Math.PI) / names.length;

            names.forEach((name, i) => {
                ctx.beginPath();
                ctx.moveTo(center, center);
                ctx.arc(center, center, radius, angle + i * slice, angle + (i + 1) * slice);
                ctx.fillStyle = colors[i % colors.length];
                ctx.fill();
                ctx.lineWidth = 5;
                ctx.strokeStyle = '#ffffff';
                ctx.stroke();

                ctx.save();
                ctx.translate(center, center);
                ctx.rotate(angle + i * slice + slice / 2);
                ctx.textAlign = 'right';
                ctx.fillStyle = '#ffffff';
                ctx.font = names.length > 12 ? 'bold 24px Inter, sans-serif' : 'bold 30px Inter, sans-serif';
                ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
                ctx.shadowBlur = 4;

                let displayName = name;
                if (displayName.length > 14) {
                    displayName = displayName.substring(0, 12) + '...';
                }
                ctx.fillText(displayName, radius - 45, 10);
                ctx.restore();
            });
        }

        function handleQuickSpin() {
            if (isSpinning) return;
            if (names.length < 2) {
                shakeInput();
                showNotice("Add at least 2 players to spin!");
                return;
            }
            const velocity = (Math.random() * 0.35) + 0.55;
            executeSpin(velocity);
        }

        function startCharging() {
            if (isSpinning) return;
            if (names.length < 2) {
                shakeInput();
                showNotice("Add at least 2 players to spin!");
                return;
            }
            isCharging = true;
            chargeStartTime = Date.now();
            spinPower = 0;
            if (powerBar) powerBar.style.width = '0%';
            if (powerInterval) clearInterval(powerInterval);

            powerInterval = setInterval(() => {
                spinPower += 3.2;
                if (spinPower > 100) spinPower = 100;
                if (powerBar) powerBar.style.width = spinPower + '%';
            }, 30);
        }

        function handleGlobalRelease() {
            if (!isCharging || isSpinning) return;
            isCharging = false;
            if (powerInterval) {
                clearInterval(powerInterval);
                powerInterval = null;
            }
            const holdDuration = Date.now() - chargeStartTime;
            let velocity;
            if (holdDuration < 180) {
                velocity = (Math.random() * 0.35) + 0.55;
            } else {
                if (spinPower < 15) spinPower = 20;
                velocity = (spinPower / 100) * 0.75 + 0.3;
            }
            executeSpin(velocity);
        }

        function executeSpin(velocity) {
            if (isSpinning || names.length < 2) return;
            angularVel = velocity;
            isSpinning = true;
            if (spinBtn) {
                spinBtn.disabled = true;
                spinBtn.classList.add('opacity-50', 'pointer-events-none');
            }
            if (spinBtnText) spinBtnText.innerText = "SPINNING...";
            updateUI();
            requestAnimationFrame(animateWheel);
        }

        function animateWheel() {
            if (angularVel > 0.002) {
                angularVel *= 0.985;
                angle += angularVel;
                drawWheel();
                requestAnimationFrame(animateWheel);
            } else {
                isSpinning = false;
                if (spinBtn) {
                    spinBtn.disabled = false;
                    spinBtn.classList.remove('opacity-50', 'pointer-events-none');
                }
                if (spinBtnText) spinBtnText.innerText = "HOLD TO SPIN";
                if (powerBar) powerBar.style.width = '0%';
                updateUI();
                determineWinner();
            }
        }

        function determineWinner() {
            if (names.length === 0) return;
            const slice = (2 * Math.PI) / names.length;
            const normAngle = ((angle % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI);
            const pointerAngle = 1.5 * Math.PI;
            let index = Math.floor(((2 * Math.PI - normAngle + pointerAngle) % (2 * Math.PI)) / slice) % names.length;
            const winner = names[index];

            const fairnessToggle = document.getElementById('fairness-toggle');
            if (fairnessToggle && fairnessToggle.checked && winner === lastWinner && names.length > 2) {
                angularVel = 0.12;
                isSpinning = true;
                if (spinBtn) spinBtn.classList.add('opacity-50', 'pointer-events-none');
                requestAnimationFrame(animateWheel);
                return;
            }
            triggerWin(winner);
        }

        function setupPlatter() {
            const grid = document.getElementById('mystery-grid');
            if (!grid) return;
            grid.innerHTML = '';
            window.platterWinnerIndex = null;

            if (names.length === 0) {
                grid.innerHTML = '<div class="col-span-full text-center text-slate-400 py-12 font-medium">Add players to the list below to generate mystery platters.</div>';
                return;
            }

            window.platterWinnerIndex = Math.floor(Math.random() * names.length);

            names.forEach((name, i) => {
                const item = document.createElement('div');
                item.className = 'platter-item shuffling';
                item.style.animationDelay = (i * 0.08) + 's';
                item.dataset.index = i;
                item.dataset.name = name;
                item.setAttribute('role', 'button');
                item.setAttribute('aria-label', `Mystery Platter for ${name}`);
                item.setAttribute('tabindex', '0');

                item.innerHTML = `
                    <div class="lid"></div>
                    <div class="text-[11px] font-bold text-slate-600 mt-2 truncate max-w-[90px]" title="${escapeHtml(name)}">${escapeHtml(name)}</div>
                `;

                item.addEventListener('click', () => revealPlate(item, name, i));
                item.addEventListener('keydown', (e) => {
                    if (e.key === ' ' || e.key === 'Enter') {
                        e.preventDefault();
                        revealPlate(item, name, i);
                    }
                });

                grid.appendChild(item);
            });

            setTimeout(() => {
                document.querySelectorAll('.platter-item').forEach(el => el.classList.remove('shuffling'));
            }, 800);
        }

        function revealPlate(el, name, index) {
            if (el.classList.contains('open') || isSpinning) return;
            el.classList.add('open');

            if (index === window.platterWinnerIndex) {
                el.style.backgroundColor = gameMode === 'chest' ? '#fef3c7' : '#fee2e2';
                el.style.borderColor = gameMode === 'chest' ? '#f59e0b' : '#ef4444';
                const svgIcon = gameMode === 'chest'
                    ? `<svg class="w-10 h-10 text-amber-600 drop-shadow-md" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>`
                    : `<svg class="w-10 h-10 text-red-600 drop-shadow-md" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"></path></svg>`;
                el.innerHTML = `
                    <div class="flex flex-col items-center justify-center p-1">
                        ${svgIcon}
                        <div class="mt-1 font-black text-xs uppercase tracking-wider ${gameMode === 'chest' ? 'text-amber-800' : 'text-red-800'}">
                            ${gameMode === 'chest' ? 'CHEST PIECE!' : 'PAYS BILL!'}
                        </div>
                        <div class="text-[11px] font-bold text-slate-700 truncate max-w-[90px] mt-0.5">${escapeHtml(name)}</div>
                    </div>
                `;
                triggerWin(name);
            } else {
                el.style.backgroundColor = '#f8fafc';
                el.style.borderColor = '#cbd5e1';
                el.innerHTML = `
                    <div class="flex flex-col items-center justify-center p-1">
                        <svg class="w-8 h-8 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path>
                        </svg>
                        <div class="mt-1 font-bold text-[10px] uppercase tracking-wider text-slate-500">SAFE</div>
                        <div class="text-[11px] font-medium text-slate-500 truncate max-w-[90px] mt-0.5">${escapeHtml(name)}</div>
                    </div>
                `;
            }
        }

        function triggerWin(name) {
            lastWinner = name;
            addToHistory(name);

            // Voice Announcer
            const ttsToggle = document.getElementById('tts-toggle');
            if (ttsToggle && ttsToggle.checked && 'speechSynthesis' in window) {
                try {
                    const text = gameMode === 'chest'
                        ? `Congratulations ${name}! You win the Mandi chest piece.`
                        : `Attention! ${name} has been selected to pay the bill.`;
                    const utterance = new SpeechSynthesisUtterance(text);
                    utterance.rate = 1.0;
                    window.speechSynthesis.speak(utterance);
                } catch (e) {
                    console.warn("TTS notice:", e);
                }
            }

            // "Faaa!" Sound Effect
            const faaaToggle = document.getElementById('faaa-toggle');
            if (faaaToggle && faaaToggle.checked && faaaAudio) {
                try {
                    faaaAudio.currentTime = 0;
                    faaaAudio.volume = 0.8;
                    const playPromise = faaaAudio.play();
                    if (playPromise !== undefined) {
                        playPromise.catch(e => console.warn("Audio playback notice:", e));
                    }
                } catch (e) {
                    console.warn("Audio error:", e);
                }
            }

            // Haptic vibration
            if (navigator.vibrate) {
                try { navigator.vibrate([150, 80, 150]); } catch (e) {}
            }

            // Update Winner Modal
            const winnerNameEl = document.getElementById('winner-name');
            const winnerRoleEl = document.getElementById('winner-role');
            if (winnerNameEl) winnerNameEl.innerText = name;
            if (winnerRoleEl) {
                winnerRoleEl.innerText = gameMode === 'chest' ? "Wins the Chest Piece!" : "Pays the Bill!";
                winnerRoleEl.className = gameMode === 'chest' ? "text-amber-600 font-bold uppercase tracking-widest text-sm mb-6 px-2 break-words" : "text-red-600 font-bold uppercase tracking-widest text-sm mb-6 px-2 break-words";
            }

            const modalBadge = document.querySelector('#winner-modal .receipt-card .absolute');
            const modalIcon = document.getElementById('modal-icon');
            if (modalBadge && modalIcon) {
                if (gameMode === 'chest') {
                    modalBadge.className = "absolute -top-14 left-1/2 -translate-x-1/2 w-28 h-28 bg-gradient-to-br from-amber-300 to-amber-600 rounded-full flex items-center justify-center border-[6px] border-amber-100 shadow-[0_0_30px_rgba(253,186,116,0.5)] text-white";
                    modalIcon.innerHTML = `<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.38-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z"></path>`;
                } else {
                    modalBadge.className = "absolute -top-14 left-1/2 -translate-x-1/2 w-28 h-28 bg-gradient-to-br from-red-400 to-red-600 rounded-full flex items-center justify-center border-[6px] border-red-100 shadow-[0_0_30px_rgba(239,68,68,0.4)] text-white";
                    modalIcon.innerHTML = `<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path>`;
                }
            }

            const now = new Date();
            const dateEl = document.getElementById('receipt-date');
            const timeEl = document.getElementById('receipt-time');
            if (dateEl) dateEl.innerText = now.toLocaleDateString();
            if (timeEl) timeEl.innerText = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

            const modal = document.getElementById('winner-modal');
            if (modal) {
                modal.classList.remove('hidden');
                requestAnimationFrame(() => {
                    modal.classList.remove('opacity-0');
                    const content = modal.querySelector('#receipt-content');
                    if (content) {
                        content.classList.remove('scale-95');
                        content.classList.add('scale-100');
                    }
                });
            }
        }

        function closeModal() {
            const modal = document.getElementById('winner-modal');
            if (!modal) return;
            modal.classList.add('opacity-0');
            const content = modal.querySelector('#receipt-content');
            if (content) {
                content.classList.remove('scale-100');
                content.classList.add('scale-95');
            }
            setTimeout(() => {
                modal.classList.add('hidden');
            }, 300);
        }

        function addToHistory(name) {
            recentWinners.unshift({ name, mode: gameMode, time: new Date() });
            if (recentWinners.length > 10) recentWinners.pop();
            saveHistory();
            renderHistory();
        }

        function renderHistory() {
            const container = document.getElementById('history-log');
            if (!container) return;
            container.innerHTML = '';
            if (recentWinners.length === 0) {
                container.innerHTML = '<span class="text-sm text-slate-400 italic">No spin history available yet.</span>';
                return;
            }
            recentWinners.forEach(w => {
                const div = document.createElement('div');
                div.className = 'flex-shrink-0 flex items-center gap-3 bg-white px-4 py-3 rounded-xl border border-slate-200 shadow-sm max-w-full overflow-hidden';
                div.innerHTML = `
                    <span class="w-3 h-3 rounded-full shrink-0 ${w.mode === 'chest' ? 'bg-amber-500' : 'bg-red-500'}"></span>
                    <span class="text-sm font-bold text-slate-800 truncate max-w-[120px]" title="${escapeHtml(w.name)}">${escapeHtml(w.name)}</span>
                    <span class="text-[11px] font-medium text-slate-400 border border-slate-200 pl-3 ml-1 shrink-0">${w.time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                `;
                container.appendChild(div);
            });
        }

        function saveHistory() {
            try {
                localStorage.setItem('mandi_history', JSON.stringify(recentWinners));
            } catch (e) {}
        }

        function loadHistory() {
            try {
                const data = localStorage.getItem('mandi_history');
                if (data) {
                    recentWinners = JSON.parse(data).map(x => ({ ...x, time: new Date(x.time) }));
                    renderHistory();
                }
            } catch (e) {}
        }

        function setTip(percent) {
            const tipEl = document.getElementById('tip-percent');
            if (tipEl) tipEl.value = percent;
            calcTip();
        }

        function calcTip() {
            const billEl = document.getElementById('bill-amount');
            const tipEl = document.getElementById('tip-percent');
            const totalEl = document.getElementById('total-pay');
            if (!billEl || !totalEl) return;
            const bill = parseFloat(billEl.value) || 0;
            const tipPct = parseInt(tipEl ? tipEl.value : 0) || 0;
            const total = bill + (bill * (tipPct / 100));
            totalEl.innerText = '$' + total.toFixed(2);
        }

        function shakeInput() {
            if (!nameInput) return;
            nameInput.classList.add('border-red-500', 'ring-2', 'ring-red-200');
            nameInput.focus();
            setTimeout(() => {
                nameInput.classList.remove('border-red-500', 'ring-2', 'ring-red-200');
            }, 600);
        }

        function showNotice(msg) {
            if (!spinBtnText) return;
            const original = spinBtnText.innerText;
            spinBtnText.innerText = msg;
            setTimeout(() => {
                if (spinBtnText.innerText === msg) {
                    spinBtnText.innerText = original;
                }
            }, 2000);
        }

        function copyLink() {
            if (navigator.clipboard && window.location.href) {
                navigator.clipboard.writeText(window.location.href).then(() => {
                    alert('Tool link copied to clipboard!');
                }).catch(() => {
                    prompt('Copy this link:', window.location.href);
                });
            } else {
                prompt('Copy this link:', window.location.href);
            }
        }

        function shareLink(platform) {
            const url = encodeURIComponent(window.location.origin + window.location.pathname);
            const text = encodeURIComponent("Who gets the Mandi chest piece or pays the bill? Spin the wheel on ToolkitGen!");
            if (platform === 'wa') window.open(`https://wa.me/?text=${text}%20${url}`, '_blank', 'noopener,noreferrer');
            if (platform === 'tw') window.open(`https://twitter.com/intent/tweet?text=${text}&url=${url}`, '_blank', 'noopener,noreferrer');
        }
